SELECT 
FROM gt_investment_limit
WHERE org_id = #{orgId}

    AND limit_name LIKE CONCAT('%', #{limitName}, '%')


    AND limit_type = #{limitType}


    AND product_type = #{productType}


    AND issuer LIKE CONCAT('%', #{issuer}, '%')


    AND risk_level = #{riskLevel}


    AND limit_status = #{limitStatus}

ORDER BY create_time DESC

SELECT COALESCE(SUM(limit_amount), 0)
FROM gt_investment_limit
WHERE org_id = #{orgId}

SELECT COALESCE(SUM(used_amount), 0)
FROM gt_investment_limit
WHERE org_id = #{orgId}

SELECT COALESCE(SUM(available_amount), 0)
FROM gt_investment_limit
WHERE org_id = #{orgId}

SELECT limit_id, limit_name, 'OVER_LIMIT' as alertType, CONCAT('限额超限：使用率', ROUND(usage_rate * 100, 2), '%') as alertMessage, update_time as alertDate FROM gt_investment_limit WHERE usage_rate >= 1.0 AND org_id = #{orgId}
UNION ALL
SELECT limit_id, limit_name, 'NEAR_LIMIT' as alertType, CONCAT('接近限额：使用率', ROUND(usage_rate * 100, 2), '%') as alertMessage, update_time as alertDate FROM gt_investment_limit WHERE usage_rate >= warning_threshold AND usage_rate < 1.0 AND org_id = #{orgId}
UNION ALL
SELECT limit_id, limit_name, 'NEAR_EXPIRY' as alertType, '限额即将到期' as alertMessage, expire_date as alertDate FROM gt_investment_limit WHERE limit_status = 'ACTIVE' AND expire_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 30 DAY) AND org_id = #{orgId}

SELECT 'INCREASE_LIMIT' as recommendationType, CONCAT('建议增加限额，当前有', COUNT(*), '项限额使用率超过90%') as recommendationReason, COUNT(*) as affectedCount FROM gt_investment_limit WHERE usage_rate > 0.9 AND org_id = #{orgId}
UNION ALL
SELECT 'EXTEND_EXPIRY' as recommendationType, CONCAT('建议延长限额有效期，当前有', COUNT(*), '项限额即将到期') as recommendationReason, COUNT(*) as affectedCount FROM gt_investment_limit WHERE limit_status = 'ACTIVE' AND expire_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 30 DAY) AND org_id = #{orgId}
